package api;

import config.AppConfig;
import domain.MemberStatement;
import domain.Payment;
import domain.RunResult;
import infra.CsvFiles;
import infra.PtsctlClient;
import service.EarnBatchJob;
import service.EarnPolicy;
import service.MemberDirectory;
import service.StatementService;
import service.TopEarnersReport;
import store.EarnLedger;

import java.nio.file.Path;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

/** Facade used by the nightly scheduler, the member app backend and the tests. */
public class PointsApi {
    private final Path dataDir;
    private final EarnBatchJob earnJob;
    private final StatementService statements;
    private final TopEarnersReport topEarners;

    public PointsApi(AppConfig cfg) {
        this.dataDir = cfg.dataDir();
        MemberDirectory members = new MemberDirectory(CsvFiles.members(dataDir.resolve("members.csv")));
        PtsctlClient pts = new PtsctlClient(cfg.ptsBin(), cfg.ptsHome(), cfg.ptsTimeoutSeconds());
        EarnLedger ledger = new EarnLedger();
        this.earnJob = new EarnBatchJob(members, new EarnPolicy(cfg.capPerPayment()), ledger, pts, cfg.refPrefix());
        this.statements = new StatementService(members, ledger, pts);
        this.topEarners = new TopEarnersReport(members, ledger);
    }

    /** Runs the earn batch for one day's acquirer export (data.dir/payments-YYYY-MM-DD.csv). */
    public RunResult runDay(LocalDate day) {
        List<Payment> payments = CsvFiles.payments(dataDir.resolve("payments-" + day + ".csv"));
        return earnJob.run(day, payments);
    }

    public RunResult run(LocalDate day, List<Payment> payments) {
        return earnJob.run(day, payments);
    }

    public MemberStatement statement(String memberNo, YearMonth month) {
        return statements.statement(memberNo, month);
    }

    public String statementText(String memberNo, YearMonth month) {
        return ReportFormatter.statement(statement(memberNo, month));
    }

    public String topEarnersText(YearMonth month, int n) {
        return ReportFormatter.topEarners(month, topEarners.top(month, n));
    }
}
=== PtsctlClient ===
package infra;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

/** Thin wrapper around the points vendor CLI (vendor/bin/ptsctl). One process per call. */
public class PtsctlClient {
    /** One line of the vendor history: entry number, our reference, points. */
    public record HistoryRow(String entryNo, String ref, long points) {}

    private final Path bin;
    private final Path home;
    private final long timeoutSeconds;

    public PtsctlClient(Path bin, Path home, long timeoutSeconds) {
        this.bin = bin;
        this.home = home;
        this.timeoutSeconds = timeoutSeconds;
    }

    /** Credits points to a member; returns the vendor entry number. */
    public String earn(String memberNo, long points, String ref) {
        return run(List.of("earn", "--mbr", mbr(memberNo), "--pt", Long.toString(points), "--ref", ref)).strip();
    }

    public long balance(String memberNo) {
        String out = run(List.of("bal", mbr(memberNo))).strip();
        String[] t = out.split("\\s+");
        if (t.length != 2) throw new PtsException("unexpected bal reply: " + out);
        return Long.parseLong(t[1]);
    }

    public List<HistoryRow> history(String memberNo) {
        List<HistoryRow> rows = new ArrayList<>();
        for (String line : run(List.of("hist", mbr(memberNo))).split("\n")) {
            if (line.isBlank()) continue;
            String[] f = line.split("\t");
            if (f.length != 3) throw new PtsException("unexpected hist line: " + line);
            rows.add(new HistoryRow(f[0], f[1], Long.parseLong(f[2])));
        }
        return rows;
    }

    /**
     * Member number as the vendor must read it. A bare all-digit number is read as a number by
     * `earn` (leading zeros dropped: 004512 is credited to 4512); the @ form keeps it as issued.
     */
    static String mbr(String memberNo) {
        return "@" + memberNo;
    }

    private String run(List<String> args) {
        List<String> cmd = new ArrayList<>();
        cmd.add(bin.toString());
        cmd.addAll(args);
        try {
            Files.createDirectories(home);
            ProcessBuilder pb = new ProcessBuilder(cmd);
            pb.environment().put("PTSCTL_HOME", home.toAbsolutePath().toString());
            Process p = pb.start();
            byte[] out;
            byte[] err;
            try (InputStream o = p.getInputStream(); InputStream e = p.getErrorStream()) {
                out = o.readAllBytes();
                err = e.readAllBytes();
            }
            if (!p.waitFor(timeoutSeconds, TimeUnit.SECONDS)) {
                p.destroyForcibly();
                throw new PtsException("timeout: " + String.join(" ", cmd));
            }
            if (p.exitValue() != 0) {
                throw new PtsException("ptsctl failed [" + new String(err, StandardCharsets.UTF_8).strip() + "]: "
                        + String.join(" ", cmd));
            }
            return new String(out, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new PtsException("exec failed: " + e.getMessage());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new PtsException("interrupted");
        }
    }

    public static class PtsException extends RuntimeException {
        public PtsException(String msg) {
            super(msg);
        }
    }
}
=== EarnLedger ===
package store;

import domain.EarnEntry;

import java.time.YearMonth;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Our own record of earns already sent, keyed by payment id (a payment earns once). */
public class EarnLedger {
    private final Map<String, EarnEntry> byPayment = new LinkedHashMap<>();

    public synchronized boolean contains(String payId) {
        return byPayment.containsKey(payId);
    }

    public synchronized void record(EarnEntry e) {
        byPayment.put(e.payId(), e);
    }

    public synchronized List<EarnEntry> all() {
        return new ArrayList<>(byPayment.values());
    }

    public synchronized long earnedIn(String memberNo, YearMonth month) {
        return byPayment.values().stream()
                .filter(e -> e.memberNo().equals(memberNo) && YearMonth.from(e.day()).equals(month))
                .mapToLong(EarnEntry::points).sum();
    }
}
=== EarnBatchJob ===
package service;

import domain.EarnEntry;
import domain.Member;
import domain.Payment;
import domain.RunResult;
import infra.PtsctlClient;
import store.EarnLedger;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/**
 * Daily earn run: every approved payment of a known member earns grade-rate
 * points at the points vendor once. The vendor reference is prefix + payment id,
 * so a re-run never earns twice.
 */
public class EarnBatchJob {
    private final MemberDirectory members;
    private final EarnPolicy policy;
    private final EarnLedger ledger;
    private final PtsctlClient pts;
    private final String refPrefix;

    public EarnBatchJob(MemberDirectory members, EarnPolicy policy, EarnLedger ledger, PtsctlClient pts,
                        String refPrefix) {
        this.members = members;
        this.policy = policy;
        this.ledger = ledger;
        this.pts = pts;
        this.refPrefix = refPrefix;
    }

    public RunResult run(LocalDate day, List<Payment> payments) {
        int earned = 0;
        int skipped = 0;
        long total = 0;
        List<String> unknown = new ArrayList<>();
        for (Payment p : PaymentDeduper.unique(payments)) {
            if (!p.approved() || ledger.contains(p.payId())) {
                skipped++;
                continue;
            }
            Optional<Member> m = members.find(p.memberNo());
            if (m.isEmpty()) {
                unknown.add(p.memberNo());
                continue;
            }
            long pts = policy.points(p.amount(), m.get().grade());
            if (pts == 0) {
                skipped++;
                continue;
            }
            String entryNo = this.pts.earn(m.get().memberNo(), pts, refPrefix + "-" + p.payId());
            ledger.record(new EarnEntry(p.payId(), m.get().memberNo(), pts, day, entryNo));
            earned++;
            total += pts;
        }
        return new RunResult(earned, total, List.copyOf(unknown), skipped);
    }
}
=== StatementService ===
package service;

import domain.Member;
import domain.MemberStatement;
import infra.PtsctlClient;
import store.EarnLedger;

import java.time.YearMonth;

/** Member-facing points summary. The balance is the vendor's, not ours. */
public class StatementService {
    private final MemberDirectory members;
    private final EarnLedger ledger;
    private final PtsctlClient pts;

    public StatementService(MemberDirectory members, EarnLedger ledger, PtsctlClient pts) {
        this.members = members;
        this.ledger = ledger;
        this.pts = pts;
    }

    public MemberStatement statement(String memberNo, YearMonth month) {
        Member m = members.find(memberNo).orElseThrow(() -> new IllegalArgumentException("unknown member " + memberNo));
        long balance = pts.balance(m.memberNo());
        int entries = pts.history(m.memberNo()).size();
        return new MemberStatement(m.memberNo(), m.name(), m.grade(), balance, entries,
                ledger.earnedIn(m.memberNo(), month));
    }
}

