package service;

import domain.Member;
import infra.PtsctlClient;

/**
 * Customer-care compensation: credited at the vendor under the ticket's own reference
 * (A-<ticket>), never under the payment reference E-. The vendor accepts a reference once,
 * so a second request for the same ticket is refused there and nothing is credited twice,
 * even after a restart or a timed-out call.
 *
 * Not recorded in EarnLedger: compensation must stay out of the payment earn records
 * that the monthly top-earners list is built from.
 */
public class CompensationService {
    /** Vendor reference prefix for compensation. Must never be the payment prefix E. */
    static final String REF_PREFIX = "A";

    private final MemberDirectory members;
    private final PtsctlClient pts;

    public CompensationService(MemberDirectory members, PtsctlClient pts) {
        this.members = members;
        this.pts = pts;
    }

    /** Credits points to an issued member number for one ticket; returns the vendor entry number. */
    public String compensate(String memberNo, long points, String ticketNo) {
        Member m = members.find(memberNo).orElseThrow(() -> new IllegalArgumentException("unknown member " + memberNo));
        if (points <= 0) throw new IllegalArgumentException("points must be positive: " + points);
        if (ticketNo == null || !ticketNo.matches("[A-Za-z0-9-]{1,30}")) {
            throw new IllegalArgumentException("bad ticket no: " + ticketNo);
        }
        return pts.earn(m.memberNo(), points, REF_PREFIX + "-" + ticketNo);
    }
}

