    this.compensation = new CompensationService(members, pts);
}

/** Customer-care compensation for one support ticket; returns the vendor entry number. */
public String compensate(String memberNo, long points, String ticketNo) {
    return compensation.compensate(memberNo, points, ticketNo);
}

